    var COMPS = [{key:"intro16",name:"Evolution24 Intro 16x9",w:1920,h:1080,duration:3.5,bar:{dur:1.05,delay:0.15,step:0.07},word:{dur:0.9,delay:0.9,step:0.032,rise:0.7,blur:4},layout:"stacked",background:true,logoWidth:746.6667,line:{w:160,h:1,top:928,dur:1.9,delay:0.1},curtain:{dur:0.9,delay:2.05}},{key:"intro9",name:"Evolution24 Intro 9x16",w:1080,h:1920,duration:2.5,bar:{dur:0.6,delay:0.06,step:0.032},word:{dur:0.5,delay:0.42,step:0.016,rise:0.6,blur:0},layout:"stacked",background:true,logoWidth:777.6,line:{w:360,h:3,top:1647,dur:1.05,delay:0.1},curtain:{dur:0.6,delay:1.15}},{key:"lockup",name:"Evolution24 Lockup Build 16x9",w:1920,h:1080,duration:3,bar:{dur:0.9,delay:0.15,step:0.045,fade:0.4},word:{dur:0.8,delay:0.42,step:0.022,rise:0.4,blur:0},layout:"lockup",background:false,logoWidth:1200}];
